import { buildings, sources } from './data.js';
import { dimensions, classification, categoryURL, recordsFor } from './catalog.js';
import { esc, icon, brandIcon } from './components.js';

export function header(route){
 const context=route.dimension?dimensions[route.dimension].name:route.kind==='record'?'건축 상세 기록':route.kind==='compare'?'건축 비교':['sources','glossary','quiz','credits'].includes(route.kind)?'자료실':route.kind==='saved'?'나의 보관함':route.kind==='search'?'아카이브 검색':'한국건축 아카이브';
 return `<div class="wrap header-inner shell-header-inner"><div class="shell-header-start"><button type="button" class="panel-toggle" data-nav-toggle aria-label="메뉴 펼치기" aria-controls="site-sidebar" aria-expanded="false">${icon('menu')}<span>메뉴</span></button><a class="shell-home" href="/" aria-label="기억 한국건축 아카이브 홈">${brandIcon}<strong>기억</strong></a><span class="header-context">${esc(context)}</span></div><div class="header-tools"><a class="header-search-link" href="/search/" aria-label="아카이브 검색">${icon('search')}<span>아카이브 검색</span><kbd>/</kbd></a><a class="saved-header" href="/saved/" aria-label="나의 보관함">${icon('bookmark')}<span class="label">보관함</span><span class="saved-count" data-saved-count></span></a></div></div>`;
}

export function sidebar(route){
 const activeDimension=route.dimension||(route.kind==='record'?'types':'');
 const activeCategory=route.kind==='collection'?route.id:route.kind==='record'?classification[route.id]?.type:'';
 const item=(href,label,ico,active=false)=>`<a class="panel-link ${active?'active':''}" href="${href}" ${active?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${icon('arrow','panel-link-arrow')}</a>`;
 const resources=[['/compare/','건축 비교','compare','compare'],['/library/','출처 자료실','book','sources'],['/library/glossary/','건축 용어집','layers','glossary'],['/library/quiz/','배움 확인','bulb','quiz']];
 return `<aside id="site-sidebar" class="site-sidebar" aria-label="아카이브 메뉴"><div class="panel-brand-row"><a class="brand" href="/" aria-label="기억 홈">${brandIcon}<div class="brand-name">기억<span>한국건축 아카이브</span></div></a><button type="button" class="icon-btn panel-close" data-nav-close aria-label="메뉴 숨기기">${icon('close')}</button></div><a class="panel-search" href="/search/">${icon('search')}<span>궁금한 건축을 찾아보세요</span></a><div class="panel-scroll"><nav aria-label="주요 메뉴">${item('/','아카이브 홈','building',route.kind==='home')}<div class="panel-section-label">분류로 탐색하기</div>${Object.entries(dimensions).map(([id,d])=>`<details name="archive-dimensions" class="panel-group ${id===activeDimension?'current':''}" ${id===activeDimension?'open':''}><summary>${icon(d.icon)}<span>${d.name}</span><small class="panel-group-count" aria-label="${d.categories.length}개 분류">${d.categories.length}</small>${icon('chevron','panel-chevron')}</summary><nav class="panel-subnav" aria-label="${d.name} 하위 메뉴"><a class="panel-category-index ${route.kind==='directory'&&route.dimension===id?'active':''}" href="/${id}/" ${route.kind==='directory'&&route.dimension===id?'aria-current="page"':''}>${d.short} 한눈에 보기 ${icon('arrow')}</a>${d.categories.map(c=>`<a href="${categoryURL(id,c.id)}" class="${id===activeDimension&&c.id===activeCategory?'active':''}" ${id===activeDimension&&c.id===activeCategory?'aria-current="page"':''}><span>${esc(c.name)}</span><small>${recordsFor(id,c.id).length}</small></a>`).join('')}</nav></details>`).join('')}</nav></div><div class="panel-resources"><div class="panel-section-label">비교하고, 배워보기</div><nav class="panel-resource-grid" aria-label="비교와 학습 메뉴">${resources.map(([url,label,ico,kind])=>`<a href="${url}" ${route.kind===kind?'aria-current="page"':''}>${icon(ico)}<span>${label}</span></a>`).join('')}</nav></div><div class="panel-footer"><span>${buildings.length}개 건축 기록 <i aria-hidden="true">·</i> ${sources.length}개 원자료</span><div class="panel-footer-links"><a href="/saved/" aria-label="나의 보관함">${icon('bookmark')} 나의 보관함</a><a href="/library/photos/" aria-label="사진 출처와 이용 안내">사진 출처 ${icon('external')}</a></div></div></aside><button type="button" class="panel-backdrop" data-nav-close tabindex="-1" aria-label="메뉴 닫기"></button>`;
}
